import{_ as a,o as s,c as i,a3 as t}from"./chunks/framework.Ch_0qWu9.js";const u=JSON.parse('{"title":"Runtime images and resource preparation","description":"","frontmatter":{"sourcePath":"docs/resources.md","sourceUrl":"https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/resources.md","alternateUrl":"/TCSExam/docs/zh/resources/","alternateAnchors":{"runtime-images-and-resource-preparation":"runtime-images-and-resource-preparation","prepare-images-with-tcsexam-build":"prepare-images-with-tcsexam-build","cache-downloads-and-host-requirements":"cache-downloads-and-host-requirements","prepare-fixed-lean-source-archives":"prepare-fixed-lean-source-archives","maxsat-hidden-data":"maxsat-hidden-data","other-resource-specific-requirements":"other-resource-specific-requirements","use-an-external-image-manifest":"use-an-external-image-manifest","sharing-prepared-products":"sharing-prepared-products"}},"headers":[],"relativePath":"resources/index.md","filePath":"resources/index.md"}'),n={name:"resources/index.md"};function r(o,e,d,l,h,p){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="runtime-images-and-resource-preparation" tabindex="-1">Runtime images and resource preparation <a class="header-anchor" href="#runtime-images-and-resource-preparation" aria-label="Permalink to &quot;Runtime images and resource preparation&quot;">​</a></h1><p>This guide explains how to download fixed inputs and build local evaluation images. It is for users preparing a Docker host for TCSExam.</p><h2 id="prepare-images-with-tcsexam-build" tabindex="-1">Prepare images with <code>tcsexam build</code> <a class="header-anchor" href="#prepare-images-with-tcsexam-build" aria-label="Permalink to &quot;Prepare images with \`tcsexam build\`&quot;">​</a></h2><p>Run <code>tcsexam build</code> for the suite, tasks and Solver protocol you will evaluate. For selections containing a local Lean build, first prepare its <a href="#prepare-fixed-lean-source-archives">fixed source archives</a>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> source-inputs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --suite</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lite</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --solver-protocol</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> offline</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --suite</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lite</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --solver-protocol</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> offline</span></span></code></pre></div><p>The builder reuses verified local images, acquires a declared public image, or runs the declared local recipe. Recipes download fixed official archives, verify their sizes and hashes, transform the selected inputs and assemble the required images. Local preparation needs Docker, disk space and access to the declared sources; it needs no registry account or image upload. All thirty Solver tasks have default recipes using official downloads or fixed inputs included in the source. See the resource-specific requirements below.</p><p>Each task has a development environment and a judging environment. Data and tool images supply build inputs to these complete runtime images. Prepare them before starting the evaluation. During task execution, Harbor runs the complete images; the model environment does not perform resource preparation or start a data container. Hidden judging inputs belong only in judging images, including their inherited layers.</p><p>The <a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/assets/images.json" target="_blank" rel="noreferrer">image manifest</a> links products to recipes, content manifests and distribution conditions. A product can prefer <code>local_build</code> or <code>public_image</code> through <code>acquisition.preferred</code>. Without a preference, a pinned public image is selected when available, followed by the local recipe. Acquiring a complete image requires neither its original datasets nor intermediate data images on the execution host. A failed acquisition or build reports its error; it does not select different task data.</p><h2 id="cache-downloads-and-host-requirements" tabindex="-1">Cache, downloads and host requirements <a class="header-anchor" href="#cache-downloads-and-host-requirements" aria-label="Permalink to &quot;Cache, downloads and host requirements&quot;">​</a></h2><p>Set <code>TCSEXAM_CACHE</code> to place the preparation cache on a disk with sufficient space; its default is <code>~/.cache/tcsexam</code>. Recipes fix runtime paths, sizes, hashes and permissions. Preparation verifies cached content, coordinates concurrent calls and installs completed results atomically. An interrupted preparation is retried; a corrupt input is reported with its path so that you can remove it and reacquire the declared bytes.</p><p>Allow space for downloaded archives, extracted inputs, transformed outputs, temporary files and Docker layers. Large data preparation should run on a host sized for the selected recipe. Model execution and judging have their own CPU, memory and time limits in the task configuration.</p><p><code>HTTP_PROXY</code>, <code>HTTPS_PROXY</code> and <code>NO_PROXY</code> from the caller&#39;s environment are forwarded to downloads and build commands. <code>docker pull</code> additionally needs proxy support configured in the Docker daemon. Configure proxy credentials in the daemon; the builder rejects them as Docker build arguments.</p><p>For a fixed upstream image, the builder first tries <code>docker pull</code>. If the daemon cannot reach the registry and <a href="https://github.com/google/go-containerregistry" target="_blank" rel="noreferrer"><code>crane</code></a> is installed, it can download the pinned image directly and verify its manifest, filesystem layers and runtime configuration. Local build references are changed only in a temporary Dockerfile. Both acquisition routes populate the same image identity cache used by <code>doctor</code> and <code>run</code>.</p><h2 id="prepare-fixed-lean-source-archives" tabindex="-1">Prepare fixed Lean source archives <a class="header-anchor" href="#prepare-fixed-lean-source-archives" aria-label="Permalink to &quot;Prepare fixed Lean source archives&quot;">​</a></h2><p>Before a local Lean image build, prepare the Graphviz corresponding-source inputs:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> source-inputs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --suite</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lite</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --track</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> theorem</span></span></code></pre></div><p>The <a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/assets/environments/lean-base/graphviz-epl/source-manifest.json" target="_blank" rel="noreferrer">source manifest</a> pins Graphviz 15.0.0 and the hpcc-js/wasm wrapper commit <code>8b86e2f83cc7344aca44fb3d8aa29a227358c5c4</code>. <code>source-inputs</code> downloads their official archives, checks exact sizes and SHA-256/SHA-512 hashes, and installs them in <code>assets/environments/lean-base/graphviz-epl/source/</code>. The Lean base Dockerfile copies these archives and verifies <code>SHA256SUMS</code>. This prepares source and license materials accompanying Graphviz in the image.</p><p>Verified context files or cached archives are reused and checked on every invocation. Archive writes use bounded blocks and an atomic rename after verification. Prepared archives remain ignored by Git. To work without network access, acquire the exact declared official archives and import them:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> source-inputs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --offline</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --input</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> graphviz=/path/to/graphviz-15.0.0.tar.gz</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --input</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wrapper=/path/to/hpcc-js-wasm-8b86e2f83cc7344aca44fb3d8aa29a227358c5c4.tar.gz</span></span></code></pre></div><p><code>--offline</code> disables network downloads. Verified files already in the build context or cache, and files supplied through <code>--input</code>, remain available. Missing files, wrong sizes and wrong hashes fail before preparation. An upstream access restriction or unavailable URL is reported as a download error; retry with the same archives obtained from their official source. Acquiring a complete published Lean image skips this local source-preparation step.</p><h2 id="maxsat-hidden-data" tabindex="-1">MaxSAT hidden data <a class="header-anchor" href="#maxsat-hidden-data" aria-label="Permalink to &quot;MaxSAT hidden data&quot;">​</a></h2><p>The default recipe reconstructs the 200 MaxSAT final-judging formulas from the fixed <a href="https://zenodo.org/records/21358014" target="_blank" rel="noreferrer">MaxSAT Evaluation 2026 archive</a>. The <a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/assets/data/solver/solver-maxsat-mse-judging-data-recipe.json" target="_blank" rel="noreferrer">recipe</a> pins the archive hash, selected files, conversion parameters, random seeds and input/output formula hashes. It reproduces the declared variable and clause ordering and verifies the complete formulas and compressed outputs. Online and Offline final judging use the same hidden formulas; public self-test data is prepared separately.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --suite</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> full</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> maxsat-mse</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --solver-protocol</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> offline</span></span></code></pre></div><p>Select <code>--solver-protocol online</code> for Online. The official archive is about 1.97 GB, and transformed formulas total about 26.8 GB before compression. Reserve additional disk space for intermediate files, compressed outputs and Docker layers. Conversion uses disk-backed intermediate files to limit memory use.</p><p><code>build.download_timeout_sec</code> sets the download and retry budget. The builder adds 180 seconds for download-tool setup and verification; data processing has a separate build deadline. Task judging budgets are defined independently.</p><h2 id="other-resource-specific-requirements" tabindex="-1">Other resource-specific requirements <a class="header-anchor" href="#other-resource-specific-requirements" aria-label="Permalink to &quot;Other resource-specific requirements&quot;">​</a></h2><p>Read each entry for the additional requirements of that resource.</p><table tabindex="0"><thead><tr><th>Resource</th><th>Preparation and requirements</th></tr></thead><tbody><tr><td>BPPLIB</td><td>Python 3.12+ and system libarchive with RAR support, such as Debian/Ubuntu <code>libarchive13</code> or <code>libarchive13t64</code>. The recipe downloads 19 pinned official files and reconstructs the selected instances, example packings and development table.</td></tr><tr><td>QBF public data</td><td>The pinned ParaProofa v1 source archive is about 949 MB. The recipe reconstructs the thirteen public instances and their fixed XZ compression.</td></tr><tr><td>PACE 2021 Cluster Editing and PACE 2022 Directed Feedback Vertex Set verifiers</td><td>Recipes download the pinned official ZIP/tar.gz, compile <code>ce_verify</code> or <code>fvs_verify</code> in a digest-pinned Ubuntu 22.04 linux/amd64 builder, and check source and compiled hashes. Docker supplies the compiler environment. <code>tcsexam build</code> composes the resulting tool image into the task images.</td></tr><tr><td>PACE 2025 Hitting Set</td><td>Separate recipes reconstruct the 100 public and 100 hidden plaintext inputs from <code>MarioGrobler/PACE2025-instances</code> commit <code>e0bff608037db1f2b9eec7a7963e31b86663e1ed</code>. Hashes and HGR dimensions are checked before image construction. The hidden files need no decryption key at judging time.</td></tr><tr><td>Radiation</td><td>The default recipe verifies all 36 final-judging inputs: 24 project-generated Apache-2.0 inputs and 12 fixed MiniZinc MIT-licensed files. No separately supplied archive is required.</td></tr></tbody></table><p>In BPPLIB&#39;s development table, <code>best</code> is the published feasible upper bound, or the lower-to-upper interval when optimality is unresolved. <code>gap</code> is the first-fit-decreasing bin count minus that feasible upper bound. Use this column to compare the two constructions; use the task checker for final scoring and an optimality certificate to establish an optimum.</p><p>To inspect a prepared filesystem without building a complete image, use <code>tcsexam resources</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> resources</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --resource</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bpplib-development</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cache</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/resource-cache</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> resources</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --resource</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> qbf-public</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cache</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/resource-cache</span></span></code></pre></div><p>The QBF resource command also accepts the declared official archive through <code>--input source_archive=PATH</code>, or a hash-checked intermediate through <code>--input frozen_input=PATH</code>. Recipe declarations list all supported input names. Build and source-maintenance procedures are in <a href="/TCSExam/docs/contributing/">CONTRIBUTING</a>.</p><h2 id="use-an-external-image-manifest" tabindex="-1">Use an external image manifest <a class="header-anchor" href="#use-an-external-image-manifest" aria-label="Permalink to &quot;Use an external image manifest&quot;">​</a></h2><p>An external <code>artifacts.json</code> can select existing images instead of the default acquisition routes. It supplies immutable image references, platform, content identity and task-role assignments. Keep registry credentials outside the manifest. A task-image fragment looks like this:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;images&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;example-development&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;image&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;registry.example/tcsexam@sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;platform&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;linux/amd64&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;tasks&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;tasks/theorem/dijkstra-universal&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;development&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;example-development&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Supply actual image records for every required role, including <code>verifier</code> or online <code>backend</code>, and the selected <code>type: host_support</code> records for the Harbor helper and fixed kernel probe. The fragment above shows only a development-image assignment. <code>--image-map</code> can override task-role assignments while <code>--artifacts</code> supplies host support.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --suite</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> full</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dijkstra-universal</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --artifacts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/artifacts.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/setup.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --suite</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> full</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dijkstra-universal</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --artifacts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/artifacts.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/readiness.json</span></span></code></pre></div><p><code>setup</code> validates the selection, pulls missing images, checks digest and platform, and records availability in the cache. It also assigns Harbor support images the names expected by Harbor 0.22.0. The helper must match the installed Harbor package context, including file permissions. An unknown context requires a matching helper before acquisition can proceed.</p><p><code>--pull-policy never</code> requires local images; <code>always</code> rechecks registry acquisition. <code>--docker-context NAME</code> selects a local Unix-socket context on the Linux host running the CLI and Harbor, with shared task and job paths. Remote SSH/TCP contexts are rejected. Online backend images must also be available on the backend host. See <a href="/TCSExam/docs/running/">running evaluations</a> for readiness checks.</p><h2 id="sharing-prepared-products" tabindex="-1">Sharing prepared products <a class="header-anchor" href="#sharing-prepared-products" aria-label="Permalink to &quot;Sharing prepared products&quot;">​</a></h2><p>Follow each resource&#39;s <a href="/TCSExam/docs/licenses/distribution/">distribution conditions</a>. BPPLIB generated files and all containing images are local-only products. QBF includes three BMC instances with additional non-commercial teaching and research terms. A containing image retains every input&#39;s restrictions, including files in inherited layers. Source export is documented in <a href="/TCSExam/docs/contributing/">CONTRIBUTING</a>.</p>`,41)])])}const k=a(n,[["render",r]]);export{u as __pageData,k as default};
